from collections import deque

def max_sliding_window(xs, w):
    dq = deque()  # indices; their values fall from front to back
    out = []
    for i, x in enumerate(xs):
        if dq and dq[0] <= i - w:
            dq.popleft()
        while dq and xs[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if i >= w - 1:
            out.append(xs[dq[0]])
    return out

