from collections import deque

class RateLimiter:
    def __init__(self, k, t):
        self.k = k            # at most k orders
        self.t = t            # per t ms
        self.times = deque()  # accepted, oldest first

    def allow(self, now):
        while self.times and self.times[0] <= now - self.t:
            self.times.popleft()
        if len(self.times) < self.k:
            self.times.append(now)
            return True
        return False
